  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {node['id']: node for node in nodes}
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children[pid].append(node['id'])
    retained = set(node['id'] for node in nodes)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if node['parent'] is None:
            continue
        if node['symbol'] in required_symbols:
            continue
        if any(cid in retained for cid in children[nid]):
            continue
        can_remove = True
        for sym in required_symbols:
            count = sum(1 for n in nodes if n['id'] in retained and n['symbol'] == sym)
            if node['symbol'] == sym:
                count -= 1
            if count < 1:
                can_remove = False
                break
        if not can_remove:
            continue
        removed.append(nid)
        retained.remove(nid)
    result = {
        'removed_node_ids': removed,
        'retained_node_ids': sorted(retained)
    }
    return result"
